post_content:
{#
  =============================================================================
  SPIELPLAN-VIEW
  - Daten: Club-Einstellungen (Option) → club_matchdays = Liste der Spiele/Termine
  - Filter team_slug: Wert aus dem *aktuellen* Team-Beitrag (post.match_team_key),
    falls der View in einem Singular-Template für Post-Type "teams" läuft.
    Sonst Fallback "erste" (z. B. Startseite — dann eigenes View-Duplikat mit
    fixem team_slug anlegen oder team_slug im Template hart setzen).
  - Logo-HTML: wiederverwendbarer Part {{ include('partial-club-team-logo') }} siehe
    https://docs.metabox.io/tutorials/create-reusable-template-parts
  - Switch abgesagt: https://docs.metabox.io/fields/switch (1/0, truthy-Prüfung)
  =============================================================================
#}
{% set group = attribute(site, 'club-einstellungen') %}
{% set team_slug = (post is defined) ? (attribute(post, 'match_team_key')|default('erste')) : 'erste' %}

{% set limit = 3 %}

{% set all_matches = attribute(group, 'club_matchdays') %}

{% set matches = all_matches|length >= 1
  ? all_matches
    |filter(v => (attribute(v, 'team').value|default(attribute(v, 'team'))) == team_slug)
    |filter(v => attribute(v, 'match_datetime').timestamp < mb.microtime(true))
    |sort((a, b) => attribute(b, 'match_datetime').timestamp <=> attribute(a, 'match_datetime').timestamp)
  : []
%}

<div class="match-list-wrap">
<ul class="match-list" role="list">
  {% for clone in matches|slice(0, limit) %}
    {% set home = attribute(clone, 'home_team') %}
    {% set away = attribute(clone, 'away_team') %}
    {% set dt_iso = clone.match_datetime.timestamp|date('c') %}
    <li class="match-list__item">
      <article class="match-card match-card--past">
        <header class="match-card__head">
          <p class="match-card__league">{{ clone.league }}</p>
          <p class="match-card__when">
            <time datetime="{{ dt_iso }}">{{ clone.match_datetime.timestamp|date('d.m.Y') }}, {{ clone.match_datetime.timestamp|date('H:i') }} Uhr</time>
          </p>
        </header>
        <div class="match-lineup" role="group" aria-label="{{ home.title }} gegen {{ away.title }}{% if clone.abgesagt %}, abgesagt{% endif %}">
          <div class="match-lineup__side match-lineup__side--home">
            <p class="match-lineup__name">{{ home.title }}</p>
            {% set team_post = home %}
            {% set logo_max_width = 100 %}
            {% set logo_max_height = 100 %}
            {{ include('partial-club-team-logo') }}
          </div>
          <div class="match-lineup__center">
            {% if clone.abgesagt %}
              <p class="match-lineup__canceled" role="status">Abgesagt</p>
            {% else %}
              <p class="match-lineup__score" role="status"><span class="match-lineup__score-value">{{ clone.home_score|default('—') }}</span> <span class="match-lineup__score-sep" aria-hidden="true">:</span> <span class="match-lineup__score-value">{{ clone.away_score|default('—') }}</span></p>
            {% endif %}
          </div>
          <div class="match-lineup__side match-lineup__side--away">
            <p class="match-lineup__name">{{ away.title }}</p>
            {% set team_post = away %}
            {% set logo_max_width = 100 %}
            {% set logo_max_height = 100 %}
            {{ include('partial-club-team-logo') }}
          </div>
        </div>
      </article>
    </li>
  {% endfor %}
</ul>
</div>
